method IsDecimalWithTwoPrecision(s: string) returns (isDec: bool)
  ensures isDec == (exists i :: 0 <= i < |s| && s[i] == '.' && 
                    i + 2 < |s| && 
                    (forall j :: i+1 <= j <= i+2 ==> '0' <= s[j] <= '9') &&
                    (i + 3 == |s| || !('0' <= s[i+3] <= '9')))
  // Postcondition: isDec is true exactly when s has exactly two digits after decimal point
{
  var ix := 0;
  var iy := 0;
  var foundDecimal := false;
  var digitsAfterDecimal := 0;

  while ix < |s|
    invariant 0 <= ix <= |s|
    invariant iy == ix  // iy tracks the same position as ix
    invariant !foundDecimal ==> digitsAfterDecimal == 0
    invariant foundDecimal ==> digitsAfterDecimal == (ix - (iy when foundDecimal))
    // The main invariant: we've seen exactly digitsAfterDecimal digits after decimal
  {
    if s[ix] == '.' && !foundDecimal {
      foundDecimal := true;
      iy := ix + 1;  // iy marks position right after decimal
    } else if foundDecimal && '0' <= s[ix] <= '9' {
      digitsAfterDecimal := digitsAfterDecimal + 1;
    }

    ix := ix + 1;
  }

  // Check if we found exactly two digits after decimal
  isDec := foundDecimal && digitsAfterDecimal == 2;
}

// Helper method to demonstrate usage
method Main() {
  var test1 := "123.45";
  var test2 := "123.456";
  var test3 := "123";
  var test4 := "123.4";
  var test5 := "123.4a";

  var result1 := IsDecimalWithTwoPrecision(test1);
  var result2 := IsDecimalWithTwoPrecision(test2);
  var result3 := IsDecimalWithTwoPrecision(test3);
  var result4 := IsDecimalWithTwoPrecision(test4);
  var result5 := IsDecimalWithTwoPrecision(test5);

  print "Test '", test1, "': ", result1, "\n";
  print "Test '", test2, "': ", result2, "\n";
  print "Test '", test3, "': ", result3, "\n";
  print "Test '", test4, "': ", result4, "\n";
  print "Test '", test5, "': ", result5, "\n";

  // Verification that postconditions hold
  assert result1 == true;  // "123.45" has exactly two digits after decimal
  assert result2 == false; // "123.456" has three digits
  assert result3 == false; // "123" has no decimal
  assert result4 == false; // "123.4" has only one digit
  assert result5 == false; // "123.4a" has non-digit after decimal
}
