```dafny
method IsDecimalWithTwoPrecision(s: string) returns (isDec: bool)
  ensures isDec == (exists i :: 0 <= i < |s| && s[i] == '.' && 
                    i + 2 < |s| && 
                    (forall j :: i+1 <= j <= i+2 ==> '0' <= s[j] <= '9') &&
                    (i + 3 == |s| || !('0' <= s[i+3] <= '9')))
  // Postcondition: isDec is true exactly when s has exactly two digits after decimal point
{
  var ix := 0;
  var decimalPos := -1;  // Position of decimal point, -1 if not found
  var digitsAfterDecimal := 0;

  while ix < |s|
    invariant 0 <= ix <= |s|
    invariant decimalPos == -1 || 0 <= decimalPos < ix
    invariant digitsAfterDecimal == (if decimalPos == -1 then 0 else 
                                     (if ix <= decimalPos + 1 then 0 else 
                                      min(ix - decimalPos - 1, 2)))
    invariant decimalPos != -1 ==> s[decimalPos] == '.'
    invariant decimalPos != -1 ==> (forall j :: decimalPos < j < ix ==> '0' <= s[j] <= '9')
  {
    if s[ix] == '.' && decimalPos == -1 {
      decimalPos := ix;
    } else if decimalPos != -1 && '0' <= s[ix] <= '9' {
      if digitsAfterDecimal < 2 {
        digitsAfterDecimal := digitsAfterDecimal + 1;
      }
    }

    ix := ix + 1;
  }

  // Check if we found exactly two digits after decimal
  isDec := decimalPos != -1 && digitsAfterDecimal == 2 && 
           (decimalPos + 3 == |s| || !('0' <= s[decimalPos + 3] <= '9'));
}

